/**
 * qwerty.js — QWERTY key-adjacency map used to weight substitution/
 * transposition cost in suggest.js's edit-distance scoring (spec §6,
 * `fuzzy-matching.md` §4). ~200 bytes as a plain object per the research.
 */
const QWERTY_NEIGHBOURS = {
  a: ["q", "s", "w"],
  b: ["v", "g", "h", "n"],
  c: ["x", "d", "f", "v"],
  d: ["s", "e", "r", "f", "c", "x"],
  e: ["w", "d", "r"],
  f: ["d", "r", "t", "g", "c", "v"],
  g: ["f", "t", "y", "h", "v", "b"],
  h: ["g", "y", "u", "j", "b", "n"],
  i: ["u", "k", "o"],
  j: ["h", "u", "i", "k", "m", "n"],
  k: ["j", "i", "o", "l", "m"],
  l: ["k", "o", "p"],
  m: ["n", "j", "k"],
  n: ["b", "h", "j", "m"],
  o: ["i", "k", "l", "p"],
  p: ["o", "l"],
  q: ["w", "a"],
  r: ["e", "d", "f", "t"],
  s: ["a", "w", "e", "d", "x", "z"],
  t: ["r", "f", "g", "y"],
  u: ["y", "h", "j", "i"],
  v: ["c", "f", "g", "b"],
  w: ["q", "a", "s", "e"],
  x: ["z", "s", "d", "c"],
  y: ["t", "g", "h", "u"],
  z: ["x", "s", "a"],
};

function areAdjacent(a, b) {
  const neighbours = QWERTY_NEIGHBOURS[a.toLowerCase()];
  return !!neighbours && neighbours.includes(b.toLowerCase());
}



/* ---- src/distance.js ---- */

/**
 * distance.js — weighted OSA (optimal-string-alignment) Damerau-Levenshtein
 * distance with QWERTY-adjacency-weighted substitution/transposition cost
 * (spec §6; `fuzzy-matching.md` §1/§4). Two-row space optimisation.
 *
 * A QWERTY-adjacent substitution or transposition costs 0.5 instead of 1.0,
 * so "teh"->"the" (adjacent transposition) ranks closer than "teh"->"tea"
 * (non-adjacent substitution) at the same raw edit count.
 */

const SUB_COST_ADJACENT = 0.5;
const SUB_COST_DEFAULT = 1.0;
const INDEL_COST = 1.0;

/**
 * weightedOSADistance(a, b, maxDist = Infinity) -> number
 * Returns the weighted OSA distance, or `maxDist + 1` if it provably
 * exceeds `maxDist` (early-exit, mirrors the research's pseudocode).
 */
function weightedOSADistance(a, b, maxDist = Infinity) {
  if (Math.abs(a.length - b.length) > maxDist) return maxDist + 1;
  const len1 = a.length;
  const len2 = b.length;

  // OSA's transposition rule needs the row from TWO steps back (d[i-2][j-2]),
  // not one (a naive two-row version — including the research pseudocode
  // this was first drafted from — silently degrades to plain weighted
  // Levenshtein, undercounting transpositions as distance 2 instead of 1;
  // caught by this file's own tests, e.g. "teh"->"the" must be 1). Three
  // rows are kept for that reason; still O(min(m,n)) space, just x3.
  let prevPrev = new Array(len2 + 1).fill(Infinity);
  let prev = new Array(len2 + 1);
  let curr = new Array(len2 + 1);
  for (let j = 0; j <= len2; j++) prev[j] = j;

  for (let i = 1; i <= len1; i++) {
    curr[0] = i;
    let minInRow = i;

    for (let j = 1; j <= len2; j++) {
      const same = a[i - 1] === b[j - 1];
      const subCost = same ? 0 : (areAdjacent(a[i - 1], b[j - 1]) ? SUB_COST_ADJACENT : SUB_COST_DEFAULT);

      const del = curr[j - 1] + INDEL_COST;
      const ins = prev[j] + INDEL_COST;
      const sub = prev[j - 1] + subCost;
      curr[j] = Math.min(del, ins, sub);

      if (
        i > 1 && j > 1 &&
        a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]
      ) {
        const transposeCost = areAdjacent(a[i - 1], a[i - 2]) ? SUB_COST_ADJACENT : SUB_COST_DEFAULT;
        curr[j] = Math.min(curr[j], prevPrev[j - 2] + transposeCost);
      }

      if (curr[j] < minInRow) minInRow = curr[j];
    }

    if (minInRow > maxDist) return maxDist + 1;
    [prevPrev, prev, curr] = [prev, curr, prevPrev];
  }

  return prev[len2];
}



/* ---- src/metaphone.js ---- */

/**
 * metaphone.js — classic (single-key) Metaphone phonetic encoding.
 *
 * Implements Lawrence Philips' 1990 Metaphone algorithm (a public-domain
 * rule set, independently implemented here from the published rule
 * description — no code copied from any licensed implementation). Used to
 * catch irregular spellings ("necessery" -> "necessary") that plain
 * edit-distance misses.
 *
 * IMPORTANT: this file is mirrored rule-for-rule in
 * `build/build_spelling_db.py`'s `metaphone()` function so the phonetic
 * codes computed at dictionary-build time (Python) match the codes computed
 * at suggestion time (this file, in the browser) — they must join on equal
 * strings. If you change a rule here, change it there too;
 * `bench/check_metaphone_parity.mjs` verifies parity against a word sample
 * and must be re-run after any edit to either side.
 */

const VOWELS = new Set(["A", "E", "I", "O", "U"]);
const isVowel = (ch) => VOWELS.has(ch);

/**
 * metaphone(word) -> string
 * Returns the classic Metaphone code for `word` — letters only, uppercase,
 * variable length (not truncated to 4 chars: this module only needs the
 * code for equality matching, not display).
 */
function metaphone(word) {
  if (typeof word !== "string") return "";

  let raw = word.toUpperCase().replace(/[^A-Z]/g, "");
  if (raw.length === 0) return "";

  // Initial-letter drops (rule 2).
  if (/^(KN|GN|PN|AE|WR)/.test(raw)) {
    raw = raw.slice(1);
  } else if (raw[0] === "X") {
    raw = "S" + raw.slice(1);
  } else if (/^WH/.test(raw)) {
    raw = "W" + raw.slice(2);
  }
  if (raw.length === 0) return "";

  // Collapse duplicate adjacent letters, except CC (rule 1).
  let w = raw[0];
  for (let i = 1; i < raw.length; i++) {
    if (raw[i] === raw[i - 1] && raw[i] !== "C") continue;
    w += raw[i];
  }

  const n = w.length;
  let out = "";
  let skip = 0; // number of upcoming characters already consumed by a digraph

  for (let i = 0; i < n; i++) {
    if (skip > 0) {
      skip--;
      continue;
    }
    const c = w[i];
    const prev = i > 0 ? w[i - 1] : "";
    const next = i + 1 < n ? w[i + 1] : "";
    const next2 = i + 2 < n ? w[i + 2] : "";
    const isFirst = i === 0;

    if (isVowel(c)) {
      if (isFirst) out += c; // rule 20
      continue;
    }

    switch (c) {
      case "B":
        if (!(i === n - 1 && prev === "M")) out += "B"; // rule 3
        break;

      case "C":
        if (next === "I" && next2 === "A") {
          out += "X";
        } else if (next === "H") {
          out += prev === "S" ? "" : "X";
          skip = 1;
        } else if (next === "I" || next === "E" || next === "Y") {
          out += "S";
        } else {
          out += "K";
        }
        break;

      case "D":
        if (next === "G" && (next2 === "E" || next2 === "Y" || next2 === "I")) {
          out += "J";
          skip = 1;
        } else {
          out += "T";
        }
        break;

      case "G": {
        if (next === "H") {
          const afterH = i + 2 < n ? w[i + 2] : "";
          if (!isVowel(afterH)) {
            skip = 1; // silent GH
            break;
          }
          out += "K";
          skip = 1;
          break;
        }
        if (next === "N") {
          const rest = w.slice(i + 2);
          if (rest === "" || rest === "ED") {
            skip = rest.length + 1; // silent GN / GNED at end
            break;
          }
        }
        if ((next === "I" || next === "E" || next === "Y") && prev !== "G") {
          out += "J";
        } else {
          out += "K";
        }
        break;
      }

      case "H":
        if (isVowel(prev) && !isVowel(next)) {
          // silent — vowel-H-consonant
        } else if ("CSPTG".includes(prev)) {
          // silent after these (already folded into their own rules mostly)
        } else {
          out += "H";
        }
        break;

      case "K":
        if (prev !== "C") out += "K";
        break;

      case "P":
        if (next === "H") {
          out += "F";
          skip = 1;
        } else {
          out += "P";
        }
        break;

      case "Q":
        out += "K";
        break;

      case "S":
        if (next === "I" && (next2 === "O" || next2 === "A")) {
          out += "X";
        } else if (next === "H") {
          out += "X";
          skip = 1;
        } else {
          out += "S";
        }
        break;

      case "T":
        if (next === "I" && (next2 === "O" || next2 === "A")) {
          out += "X";
        } else if (next === "H") {
          out += "0"; // theta
          skip = 1;
        } else {
          out += "T";
        }
        break;

      case "V":
        out += "F";
        break;

      case "W":
        if (isVowel(next)) out += "W";
        break;

      case "X":
        out += "KS";
        break;

      case "Y":
        if (isVowel(next)) out += "Y";
        break;

      case "Z":
        out += "S";
        break;

      default: // F J L M N R
        out += c;
        break;
    }
  }

  return out;
}



/* ---- src/tokenizer.js ---- */

/**
 * tokenizer.js — the Spelling module's own tokenizer (spec FR-8, plan D-5).
 *
 * Self-contained: does not call any host's `ENGINE.tokenize()`. This is the
 * one dependency plan D-5 explicitly cuts, so the module works standalone.
 *
 * tokenize(text) -> SpellToken[]  where SpellToken = {text, start, end, isWord}
 * Offsets are character-accurate against the ORIGINAL input string.
 */

// Curly apostrophes normalise to straight ones for boundary detection only
// (rule 1) — both are single UTF-16 code units, so the substitution never
// shifts offsets, and the token `text` below is sliced from the ORIGINAL
// string so a returned token still shows the user's own curly quote.
const CURLY_APOSTROPHE_RE = /[’‘]/g;

function normalizeApostrophes(text) {
  return text.replace(CURLY_APOSTROPHE_RE, "'");
}

// One master regex, alternatives tried left-to-right at each position —
// this IS the rule-order from FR-8 (url/email/number win over a generic
// word run; a word run itself absorbs contractions, hyphenated compounds,
// and ALL-CAPS-with-trailing-digits in one match, since none of those need
// a different token *boundary*, only different downstream classification).
const URL_ALT = String.raw`https?:\/\/\S+|www\.[^\s]+`;
const EMAIL_ALT = String.raw`[\w.+-]+@[\w-]+\.[\w.-]+`;
const NUMBER_ALT = String.raw`\d+(?:[.,]\d+)*`;
// letters, optionally joined by ' or - to more letters (contractions,
// hyphenated compounds), optionally followed by trailing digits (NASA2).
const WORD_ALT = String.raw`[A-Za-z]+(?:['-][A-Za-z]+)*\d*`;
const WHITESPACE_ALT = String.raw`\s+`;
const PUNCT_ALT = String.raw`[^\sA-Za-z0-9]+`;

const TOKEN_RE = new RegExp(
  `(${URL_ALT})|(${EMAIL_ALT})|(${NUMBER_ALT})|(${WORD_ALT})|(${WHITESPACE_ALT})|(${PUNCT_ALT})`,
  "g"
);

/**
 * tokenize(text: string) -> SpellToken[]
 */
function tokenize(text) {
  if (typeof text !== "string" || text.length === 0) return [];

  const normalized = normalizeApostrophes(text);
  const tokens = [];
  TOKEN_RE.lastIndex = 0;

  let match;
  while ((match = TOKEN_RE.exec(normalized)) !== null) {
    const start = match.index;
    const end = start + match[0].length;
    // group 4 is the WORD_ALT capture -> the only isWord:true class.
    const isWord = match[4] !== undefined;
    tokens.push({
      text: text.slice(start, end),
      start,
      end,
      isWord,
    });
  }

  return tokens;
}

/** isAllCaps(word) -> true for a run of 2+ uppercase letters, optional
 * trailing digits (FR-8 rule 7 / §4 rule 3), e.g. "NASA", "NASA2". */
function isAllCaps(word) {
  return /^[A-Z]{2,}\d*$/.test(word);
}

/** isCamelCase(word) -> true for a mixed-case run that is not simple
 * sentence-case (single leading capital, rest lowercase) — catches
 * "iPhone", "getElementById" (FR-8 rule 8 / §4 rule 4). Requires 4+ chars
 * per the research's CamelCase exception threshold. */
function isCamelCase(word) {
  if (word.length < 4) return false;
  if (!/[a-z]/.test(word) || !/[A-Z]/.test(word)) return false;
  return !/^[A-Z][a-z]*$/.test(word);
}

/** isContraction(word) -> true if the token contains an apostrophe within
 * a run of letters (FR-8 rule 5 / §4 rule 7). */
function isContraction(word) {
  return word.includes("'");
}

/** isHyphenatedCompound(word) -> true if the token contains a hyphen within
 * a run of letters (FR-8 rule 6 / §4 rule 8). */
function isHyphenatedCompound(word) {
  return word.includes("-");
}



/* ---- src/rules.js ---- */

/**
 * rules.js — the misspelled-or-not pass (spec §4, FR-4, FR-7).
 *
 * Rule order (first match wins, "accept" = not misspelled), ten rules per
 * spec §4.
 *
 * MEASURED DEVIATION from §4 as literally written (documented per the task
 * brief's "say so and explain what you built instead" instruction): §4 has
 * no rule that exempts a capitalised proper noun that (a) is not literally
 * in the dictionary and (b) is not sentence-initial — which is most proper
 * nouns in running text ("I visited Melbourne last year"). The shipped
 * dictionary deliberately excludes SCOWL's higher-tier proper-names lists
 * (see build/build_spelling_db.py's DEFAULT_CATEGORIES comment) — common
 * world place/person names like "Melbourne" or "London" only appear in
 * SCOWL at tier 80+, tens of thousands of extra entries past the file-size
 * budget. bench/benchmark.mjs's first run measured a 65.8% false-positive
 * rate on a 231-word proper-noun/jargon holdout without a fix for this.
 * Given spec §4's own framing — false positives are "the primary failure
 * mode... weighted above suggestion recall" — rule 5 is widened here to
 * accept any simple Title-Case token (one leading capital, rest lowercase,
 * 3+ letters) at a NON-sentence-initial position. Sentence-initial position
 * keeps the spec's exact literal behaviour — "Teh" at a sentence start must
 * still flag, per §4's own worked example — because check() (below) tracks
 * sentence boundaries and only applies the widened exemption when a token
 * is not the first word of its sentence, where "this looks like a proper
 * noun" is a much safer inference. Re-measured false-positive rate after
 * this change is recorded in README.md; if it still exceeds the 2% budget,
 * the next lever is re-adding SCOWL's proper-names at a higher tier, not
 * further loosening this rule.
 */


// Longest-suffix-first so "-ness" isn't mistaken for a stray "-s" strip.
const SUFFIXES_LONGEST_FIRST = [
  "tion", "ness", "ment",
  "ity", "ful", "ize", "ise", "ing", "est",
  "ed", "er", "es", "ly",
  "s",
];

const CONTRACTION_WHITELIST = new Set([
  "don't", "doesn't", "didn't", "isn't", "aren't", "wasn't", "weren't",
  "haven't", "hasn't", "hadn't", "won't", "wouldn't", "can't", "couldn't",
  "shouldn't", "mustn't", "it's", "that's", "there's", "here's", "what's",
  "who's", "let's", "i'm", "you're", "we're", "they're", "i've", "you've",
  "we've", "they've", "i'd", "you'd", "he'd", "she'd", "we'd", "they'd",
  "i'll", "you'll", "he'll", "she'll", "we'll", "they'll", "y'all",
  "o'clock", "ma'am",
]);

// Title-Case shape used by the widened rule 5: one leading capital, rest
// lowercase, 3+ letters — e.g. "Melbourne", "Shakespeare".
const TITLE_CASE_RE = /^[A-Z][a-z]{2,}$/;

function isTitleCaseWord(word) {
  return TITLE_CASE_RE.test(word);
}

/** rule 6 — morphological variants (suffix strip, e-drop, doubled-consonant
 * undo, y<->ies). Operates on an already-lowercased word. */
function isMorphologicallyValid(word, backend) {
  if (word.endsWith("ies") && word.length > 4) {
    if (backend.has(word.slice(0, -3) + "y")) return true;
  }
  for (const suf of SUFFIXES_LONGEST_FIRST) {
    if (word.length <= suf.length + 2 || !word.endsWith(suf)) continue;
    const base = word.slice(0, -suf.length);
    if (backend.has(base)) return true;
    if (backend.has(base + "e")) return true; // e-drop: "making" -> "mak" + "e"
    const last = base[base.length - 1];
    const secondLast = base[base.length - 2];
    if (base.length > 2 && last === secondLast && backend.has(base.slice(0, -1))) {
      return true; // doubled consonant: "running" -> "runn" -> "run"
    }
  }
  return false;
}

/** rule 7 — contractions: whole-token whitelist, else naive split. */
function isValidContraction(lowerWord, backend) {
  if (CONTRACTION_WHITELIST.has(lowerWord)) return true;
  const parts = lowerWord.split("'");
  if (parts.length !== 2) return false;
  const [head, tail] = parts;
  if (!backend.has(head)) return false;
  const commonClitics = new Set(["s", "t", "d", "ll", "re", "ve", "m"]);
  return commonClitics.has(tail) || backend.has(tail);
}

/** rule 8 — hyphenated compounds: every '-'-separated part passes rule 1 or 6. */
function isValidHyphenatedCompound(lowerWord, backend) {
  const parts = lowerWord.split("-").filter(Boolean);
  if (parts.length < 2) return false;
  return parts.every((p) => backend.has(p) || isMorphologicallyValid(p, backend));
}

/**
 * classifyWord(word, ctx, position) -> { accepted: boolean, rule?: number }
 * ctx = { backend: DictionaryBackend, isIgnored: (w)=>bool, isLearned: (w)=>bool }
 * position = { sentenceInitial?: boolean } — see file header re: rule 5.
 */
function classifyWord(word, ctx, position = {}) {
  const lower = word.toLowerCase();

  if (ctx.backend.has(lower)) return { accepted: true, rule: 1 };
  if (ctx.isIgnored(word) || ctx.isLearned(word)) return { accepted: true, rule: 2 };
  if (isAllCaps(word)) return { accepted: true, rule: 3 };
  if (isCamelCase(word)) return { accepted: true, rule: 4 };
  if (!position.sentenceInitial && isTitleCaseWord(word)) return { accepted: true, rule: 5 };
  if (isMorphologicallyValid(lower, ctx.backend)) return { accepted: true, rule: 6 };
  if (isContraction(word) && isValidContraction(lower, ctx.backend)) {
    return { accepted: true, rule: 7 };
  }
  if (isHyphenatedCompound(word) && isValidHyphenatedCompound(lower, ctx.backend)) {
    return { accepted: true, rule: 8 };
  }
  return { accepted: false };
}

const SENTENCE_BOUNDARY_RE = /[.!?\n]/;

/**
 * check(tokens, ctx) -> MisspelledToken[]
 * `tokens` is the tokenizer's SpellToken[] output. `ctx` is the same shape
 * classifyWord takes. Returns entries for words that fail every rule
 * (`{word, start, end}`) AND, separately, immediately-repeated words
 * (`{word, start, end, kind: "repeat"}`, spec §4 rule 9) — a repeat can fire
 * even on a correctly-spelled word, so it is not gated on classifyWord's
 * result.
 */
function check(tokens, ctx) {
  const findings = [];
  let previousWordToken = null;
  let previousWasSentenceBoundary = true;

  for (const token of tokens) {
    if (!token.isWord) {
      if (SENTENCE_BOUNDARY_RE.test(token.text)) previousWasSentenceBoundary = true;
      continue;
    }

    if (
      previousWordToken &&
      previousWordToken.text.toLowerCase() === token.text.toLowerCase() &&
      !previousWasSentenceBoundary
    ) {
      findings.push({ word: token.text, start: token.start, end: token.end, kind: "repeat" });
    }

    const decision = classifyWord(token.text, ctx, { sentenceInitial: previousWasSentenceBoundary });
    if (!decision.accepted) {
      findings.push({ word: token.text, start: token.start, end: token.end });
    }

    previousWordToken = token;
    previousWasSentenceBoundary = false;
  }

  return findings;
}



